package httpapi
import("encoding/json";"errors";"io";"net/http";"strings";"time";"github.com/LeonQin-ai/light-agent/control/internal/store")
type Server struct{s store.Store;m *http.ServeMux}
func New(st store.Store,wh http.Handler)*Server{x:=&Server{s:st,m:http.NewServeMux()};x.m.HandleFunc("GET /healthz",x.health);x.m.HandleFunc("POST /v1/agents",x.createAgent);x.m.HandleFunc("GET /v1/agents/{id}",x.getAgent);x.m.HandleFunc("GET /v1/agents/{id}/runtime",x.runtime);x.m.HandleFunc("POST /v1/agents/{id}/messages",x.submit);x.m.HandleFunc("GET /v1/tasks/{id}",x.task);x.m.HandleFunc("POST /v1/tasks/{id}/cancel",x.cancel);if wh!=nil{x.m.Handle("POST /webhooks/feishu",wh)};return x}
func(x *Server)ServeHTTP(w http.ResponseWriter,r *http.Request){x.m.ServeHTTP(w,r)}
func(x *Server)health(w http.ResponseWriter,_ *http.Request){jsonOut(w,200,map[string]string{"status":"ok"})}
func(x *Server)createAgent(w http.ResponseWriter,r *http.Request){var q struct{Tenant string `json:"tenant_id"`;Role string `json:"role"`};if e:=decode(w,r,&q);e!=nil{fail(w,400,"invalid_request",e.Error());return};a,e:=x.s.CreateAgent(r.Context(),strings.TrimSpace(q.Tenant),q.Role);if e!=nil{fail(w,400,"agent_create_failed",e.Error());return};jsonOut(w,201,a)}
func(x *Server)getAgent(w http.ResponseWriter,r *http.Request){a,e:=x.s.GetAgent(r.Context(),r.PathValue("id"));if e!=nil{storeErr(w,e);return};jsonOut(w,200,a)}
func(x *Server)runtime(w http.ResponseWriter,r *http.Request){a,e:=x.s.GetAgent(r.Context(),r.PathValue("id"));if e!=nil{storeErr(w,e);return};jsonOut(w,200,map[string]any{"agent_id":a.ID,"runtime_state":"ABSENT","runtime_id":nil,"generation":a.Generation,"note":"runtime lifecycle is M2; identity creation starts no process or VM"})}
func(x *Server)submit(w http.ResponseWriter,r *http.Request){var q struct{RequestID string `json:"request_id"`;Content string `json:"content"`};if e:=decode(w,r,&q);e!=nil{fail(w,400,"invalid_request",e.Error());return};q.Content=strings.TrimSpace(q.Content);if q.Content==""{fail(w,400,"invalid_request","content required");return};if q.RequestID==""{q.RequestID=r.Header.Get("Idempotency-Key")};p,_:=json.Marshal(map[string]string{"source":"api","content":q.Content});t,e:=x.s.CreateTask(r.Context(),r.PathValue("id"),q.RequestID,string(p));if e!=nil{storeErr(w,e);return};jsonOut(w,202,t)}
func(x *Server)task(w http.ResponseWriter,r *http.Request){t,e:=x.s.GetTask(r.Context(),r.PathValue("id"));if e!=nil{storeErr(w,e);return};jsonOut(w,200,t)}
func(x *Server)cancel(w http.ResponseWriter,r *http.Request){t,e:=x.s.CancelTask(r.Context(),r.PathValue("id"));if e!=nil{storeErr(w,e);return};jsonOut(w,200,t)}
func decode(w http.ResponseWriter,r *http.Request,v any)error{r.Body=http.MaxBytesReader(w,r.Body,1<<20);d:=json.NewDecoder(r.Body);d.DisallowUnknownFields();if e:=d.Decode(v);e!=nil{return e};if e:=d.Decode(&struct{}{});!errors.Is(e,io.EOF){return errors.New("expected one JSON object")};return nil}
func storeErr(w http.ResponseWriter,e error){if errors.Is(e,store.ErrNotFound){fail(w,404,"not_found","resource not found")}else{fail(w,500,"internal_error","storage error")}}
func fail(w http.ResponseWriter,s int,c,m string){jsonOut(w,s,map[string]string{"error":c,"message":m})}
func jsonOut(w http.ResponseWriter,s int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(s);_=json.NewEncoder(w).Encode(v)}
func HTTPServer(addr string,h http.Handler)*http.Server{return &http.Server{Addr:addr,Handler:h,ReadHeaderTimeout:5*time.Second,ReadTimeout:15*time.Second,WriteTimeout:30*time.Second,IdleTimeout:60*time.Second}}
